-- PostgreSQL baseline. Legacy SQLite migrations are import fixtures only.
CREATE TABLE "api_budget" ("month" TEXT NOT NULL,"committed" BIGINT NOT NULL DEFAULT 0,PRIMARY KEY ("month"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "api_calls" ("id" TEXT NOT NULL,"month" TEXT NOT NULL,"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"reserved" BIGINT NOT NULL,"actual" BIGINT,"status" TEXT NOT NULL,"data" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "bot_news_consent" ("provider" TEXT NOT NULL,"subject" TEXT NOT NULL,"subscribed" BIGINT NOT NULL DEFAULT 0,"updated_at" BIGINT NOT NULL,"consent_version" TEXT NOT NULL,PRIMARY KEY ("provider","subject"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "bot_news_deliveries" ("campaign" TEXT NOT NULL,"provider" TEXT NOT NULL,"subject" TEXT NOT NULL,"status" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("campaign","provider","subject"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_accounts" ("id" TEXT,"provider" TEXT NOT NULL,"subject" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_grants" ("id" TEXT,"buyer_id" TEXT NOT NULL,"remaining" BIGINT NOT NULL,"expires_at" BIGINT,"kind" TEXT NOT NULL,"test" BIGINT NOT NULL DEFAULT 0,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_identities" ("provider" TEXT NOT NULL,"subject" TEXT NOT NULL,"buyer_id" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("provider","subject"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_logins" ("hash" TEXT,"browser_hash" TEXT NOT NULL,"provider" TEXT NOT NULL,"expires_at" BIGINT NOT NULL,"code_hash" TEXT,"subject" TEXT,"name" TEXT,"attempts" BIGINT NOT NULL DEFAULT 0,"consumed" BIGINT NOT NULL DEFAULT 0,"link_buyer_id" TEXT,PRIMARY KEY ("hash"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_payments" ("id" TEXT,"buyer_id" TEXT NOT NULL,"provider_id" TEXT,"amount" BIGINT NOT NULL,"searches" BIGINT NOT NULL,"days" BIGINT NOT NULL,"test" BIGINT NOT NULL,"status" TEXT NOT NULL,"confirmation_url" TEXT,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_personal" ("buyer_id" TEXT,"data" TEXT NOT NULL,"version" BIGINT NOT NULL DEFAULT 1,"updated_at" BIGINT NOT NULL,PRIMARY KEY ("buyer_id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_searches" ("id" TEXT,"buyer_id" TEXT NOT NULL,"grant_id" TEXT NOT NULL,"status" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "buyer_sessions" ("hash" TEXT,"buyer_id" TEXT NOT NULL,"expires_at" BIGINT NOT NULL,"login_provider" TEXT,PRIMARY KEY ("hash"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "claims" ("id" TEXT NOT NULL,"store_id" TEXT NOT NULL,"applicant" TEXT NOT NULL,"status" TEXT NOT NULL,"data" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "connection_requests" ("id" TEXT NOT NULL,"data" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"created_at" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "discovered_offers" ("id" TEXT NOT NULL,"city" TEXT NOT NULL,"source_key" TEXT NOT NULL,"source_url" TEXT NOT NULL,"data" TEXT NOT NULL,"checked_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "discovery_limits" ("id" TEXT NOT NULL,"count" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "discovery_sources" ("id" TEXT NOT NULL,"data" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "external_places" ("id" TEXT NOT NULL,"city" TEXT NOT NULL,"category" TEXT NOT NULL,"data" TEXT NOT NULL,"checked_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "favorites" ("customer" TEXT NOT NULL,"product_id" TEXT NOT NULL,PRIMARY KEY ("customer","product_id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "inquiries" ("id" TEXT NOT NULL,"store_id" TEXT NOT NULL,"customer" TEXT NOT NULL,"data" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "onboarding" ("store_id" TEXT NOT NULL,"created_by" TEXT NOT NULL,"created_at" TEXT NOT NULL,"consent" TEXT,"confirmed_at" TEXT,PRIMARY KEY ("store_id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "owner_accounts" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "owner_invites" ("hash" TEXT NOT NULL,"store_id" TEXT NOT NULL,"email" TEXT NOT NULL,"expires_at" TEXT NOT NULL,"used_at" TEXT,PRIMARY KEY ("hash"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "owner_sessions" ("hash" TEXT NOT NULL,"user_id" TEXT NOT NULL,"expires_at" BIGINT NOT NULL,PRIMARY KEY ("hash"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "payment_audit" ("id" TEXT,"order_id" TEXT NOT NULL,"status" TEXT NOT NULL,"test" BIGINT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "preview_tokens" ("hash" TEXT NOT NULL,"store_id" TEXT NOT NULL,"expires_at" TEXT NOT NULL,"revoked" BIGINT NOT NULL DEFAULT 0,PRIMARY KEY ("hash"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "product_events" ("id" TEXT,"event" TEXT NOT NULL,"city" TEXT NOT NULL,"category" TEXT NOT NULL,"day_actor" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "products" ("id" TEXT NOT NULL,"store_id" TEXT NOT NULL,"published" BIGINT NOT NULL,"data" TEXT NOT NULL,"normalized_name" TEXT,"source_type" TEXT,"source_url" TEXT,"checked_at" BIGINT,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "search_cache" ("id" TEXT NOT NULL,"data" TEXT NOT NULL,"expires_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "search_locks" ("id" TEXT NOT NULL,"until_ms" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "search_metrics" ("id" TEXT NOT NULL,"data" TEXT NOT NULL,"created_at" BIGINT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "searches" ("id" TEXT NOT NULL,"query" TEXT NOT NULL,"result_count" BIGINT NOT NULL,"created_at" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "shopping_plans" ("id" TEXT NOT NULL,"owner" TEXT NOT NULL,"data" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "shops" ("id" TEXT NOT NULL,"owner" TEXT,"data" TEXT NOT NULL,"visibility" TEXT NOT NULL DEFAULT 'public',PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "uploads" ("id" TEXT NOT NULL,"owner" TEXT NOT NULL,"mime" TEXT NOT NULL,PRIMARY KEY ("id"),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE INDEX "idx_api_calls_month" ON "api_calls" ("month");
CREATE UNIQUE INDEX "unique_buyer_accounts_0" ON "buyer_accounts" ("provider","subject");
CREATE INDEX buyer_grants_owner ON buyer_grants(buyer_id,expires_at);
CREATE INDEX buyer_identities_account ON buyer_identities(buyer_id);
CREATE INDEX buyer_logins_expiry ON buyer_logins(expires_at);
CREATE UNIQUE INDEX buyer_one_pending_payment ON buyer_payments(buyer_id) WHERE status IN ('creating','pending','waiting_for_capture');
CREATE INDEX buyer_payments_owner ON buyer_payments(buyer_id,created_at);
CREATE UNIQUE INDEX "unique_buyer_payments_2" ON "buyer_payments" ("provider_id");
CREATE INDEX buyer_sessions_expiry ON buyer_sessions(expires_at);
CREATE INDEX "idx_claims_applicant" ON "claims" ("applicant");
CREATE INDEX idx_discovered_checked ON discovered_offers(checked_at);
CREATE INDEX idx_discovered_city_checked ON discovered_offers(city, checked_at);
CREATE UNIQUE INDEX idx_discovered_city_source ON discovered_offers(city, source_key);
CREATE INDEX "idx_external_city_category" ON "external_places" ("city","category");
CREATE INDEX "idx_inquiries_store" ON "inquiries" ("store_id");
CREATE INDEX "idx_inquiries_customer" ON "inquiries" ("customer");
CREATE UNIQUE INDEX "owner_accounts_email_unique" ON "owner_accounts" ("email");
CREATE INDEX "idx_invites_store" ON "owner_invites" ("store_id");
CREATE INDEX "idx_owner_session_expiry" ON "owner_sessions" ("expires_at");
CREATE INDEX payment_audit_order ON payment_audit(order_id,created_at);
CREATE INDEX "idx_preview_store" ON "preview_tokens" ("store_id");
CREATE INDEX product_events_time ON product_events(created_at,event);
CREATE INDEX idx_products_source ON products(source_type,source_url);
CREATE INDEX idx_products_normalized_name ON products(normalized_name);
CREATE INDEX "idx_products_published" ON "products" ("published");
CREATE INDEX "idx_products_store" ON "products" ("store_id");
CREATE INDEX "idx_search_cache_expiry" ON "search_cache" ("expires_at");
CREATE INDEX "idx_plans_owner" ON "shopping_plans" ("owner");
CREATE UNIQUE INDEX idx_shops_single_social_owner
ON shops(owner)
WHERE owner LIKE 'telegram:%' OR owner LIKE 'max:%';
CREATE INDEX "idx_shops_owner" ON "shops" ("owner");
ALTER TABLE buyer_grants ADD CHECK (remaining>=0);
ALTER TABLE "buyer_identities" ADD FOREIGN KEY ("buyer_id") REFERENCES "buyer_accounts" ("id");
ALTER TABLE "buyer_logins" ADD FOREIGN KEY ("link_buyer_id") REFERENCES "buyer_accounts" ("id");
ALTER TABLE "buyer_payments" ADD FOREIGN KEY ("buyer_id") REFERENCES "buyer_accounts" ("id");
ALTER TABLE "buyer_personal" ADD FOREIGN KEY ("buyer_id") REFERENCES "buyer_accounts" ("id");
ALTER TABLE "buyer_searches" ADD FOREIGN KEY ("grant_id") REFERENCES "buyer_grants" ("id");
ALTER TABLE "buyer_sessions" ADD FOREIGN KEY ("buyer_id") REFERENCES "buyer_accounts" ("id");
ALTER TABLE "claims" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
ALTER TABLE "inquiries" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
ALTER TABLE "onboarding" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
ALTER TABLE "owner_invites" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
ALTER TABLE "owner_sessions" ADD FOREIGN KEY ("user_id") REFERENCES "owner_accounts" ("id");
ALTER TABLE "preview_tokens" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
ALTER TABLE "products" ADD FOREIGN KEY ("store_id") REFERENCES "shops" ("id");
